@startuml

class InsuranceCompany {
  + CompanyName : string
  + RegistrationNumber : int
}

class PolicyType {
  + TypeName : string
}

class Policy {
  + PolicyId : int
  + CoverageAmount : double
}

class Customer {
  + CustomerId : int
  + Name : string
  + ContactInfo : string
}

class Contract {
  + ContractId : int
  + SigningDate : date
  + Status : string
}

InsuranceCompany "1" -- "*" Policy
Policy "1" -- "*" Contract
Customer "1" -- "*" Contract
PolicyType "1" -- "*" Policy

@enduml

